import { ChangeDetectionStrategy, Component, computed, input, model } from '@angular/core';

@Component({
  selector: 'aevko-pagination',
  standalone: true,
  templateUrl: './pagination.component.html',
  styleUrl: './pagination.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { role: 'navigation', '[attr.aria-label]': 'label()' },
})
export class AevkoPagination {
  readonly page = model(1);
  readonly totalPages = input.required<number>();
  readonly label = input('Pagination');
  protected readonly pages = computed(() =>
    Array.from({ length: Math.max(0, this.totalPages()) }, (_, index) => index + 1),
  );
  protected select(page: number): void {
    this.page.set(Math.min(Math.max(page, 1), Math.max(this.totalPages(), 1)));
  }
}

:host {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
}
button {
  background: var(--aevko-background, #fff);
  border: 1px solid var(--aevko-border, #e4e4e7);
  color: var(--aevko-foreground, #09090b);
  cursor: pointer;
  font: 600 0.8rem/1 var(--aevko-font-sans, sans-serif);
  min-height: 2.25rem;
  padding-inline: 0.7rem;
}
button[aria-current='page'] {
  background: var(--aevko-foreground, #09090b);
  color: var(--aevko-background, #fff);
}
button:focus-visible {
  outline: 2px solid var(--aevko-focus, #a1a1aa);
  outline-offset: 1px;
}
button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}
